. \u0421\u0435\u0442\u043a\u0430: alpha \u2208 {0.50, 0.55, 0.60, 0.65, 0.70, 0.75, 0.80, 0.85, 0.90, 0.95, 1.00} \u2014 11 \u0442\u043e\u0447\u0435\u043a, \u0441\u0433\u0443\u0449\u0435\u043d\u0438\u0435 \u0432 0.6\u20131.0 (\u043f\u0435\u0440\u0435/\u043d\u0435\u0434\u043e\u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433: \u043f\u0440\u0438 \u043c\u0430\u043b\u044b\u0445 alpha \u0442\u0435\u0440\u044f\u0435\u043c \u0440\u0435\u0430\u043b\u044c\u043d\u0443\u044e \u0434\u0438\u043d\u0430\u043c\u0438\u043a\u0443 \u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u043c \u0441\u0438\u043b\u044c\u043d\u0443\u044e \u0441\u0430\u0442\u0443\u0440\u0430\u0446\u0438\u044e \u2014 \u00abover-clipping\u00bb; \u043f\u0440\u0438 alpha=1 \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u043a\u0440\u0430\u0439\u043d\u0438\u0435 outlier-\u0432\u044b\u0431\u043e\u0440\u043e\u0447\u043d\u044b\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f, \u0440\u0430\u0441\u0442\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0435 \u0448\u043a\u0430\u043b\u0443 \u2014 \u00abunder-clipping\u00bb). \u041e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 \u043e\u043f\u0442\u0438\u043c\u0443\u043c \u0434\u043b\u044f LLAMA2-7B \u0430\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u0439 \u2014 \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0439 (\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0435 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435: \u043e\u0442\u0441\u0435\u0447\u0435\u043d\u0438\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u044d\u043a\u0441\u0442\u0440\u0435\u043c\u0430\u043b\u044c\u043d\u044b\u0445 outlier-\u0430\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u0439 \u0443\u043b\u0443\u0447\u0448\u0430\u0435\u0442 PPL), \u0433\u0434\u0435 \u0438\u043c\u0435\u043d\u043d\u043e \u2014 \u044d\u043c\u043f\u0438\u0440\u0438\u043a\u0430.\n\u0421\u0445\u0435\u043c\u0430 \u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0438\u044f: (\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e) INT8 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0442\u0435\u043d\u0437\u043e\u0440\u043e\u0432; \u043a\u0432\u0430\u043d\u0442\u0438\u0437\u0430\u0446\u0438\u044f \u0432\u0445\u043e\u0434\u043e\u0432/\u0430\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u0439 \u2014 \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u0430\u044f per-tensor; K \u0438 V \u043a\u044d\u0448 \u2014 \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u0430\u044f per-channel (per-head), scale=(max-min)/255, zero_point \u0438\u0437 min; softmax(QK^T) \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0432 fp16 \u043f\u043e\u0432\u0435\u0440\u0445 \u0434\u0435\u043a\u0432\u0430\u043d\u0442\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043e\u0446\u0435\u043d\u043e\u043a. (\u0432\u0430\u0440\u044c\u0438\u0440\u0443\u0435\u0442\u0441\u044f) \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 alpha, \u043e\u0431\u0449\u0438\u0439 \u0434\u043b\u044f \u0432\u0445\u043e\u0434\u043e\u0432 \u0438 KV-\u043a\u044d\u0448\u0430, \u0432 \u0433\u043b\u0430\u0432\u043d\u043e\u043c \u0441\u0432\u0438\u043f\u0435; \u043a\u0430\u043a \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u2014 \u043f\u0430\u0440\u0430 (alpha_in, alpha_kv), \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c.\n\u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b PPL: \u0434\u0430\u0442\u0430\u0441\u0435\u0442 WikiText-2 (wikitext-2-raw), test split; \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 2048 \u0442\u043e\u043a\u0435\u043d\u043e\u0432, sliding-window/stride=512 \u0442\u043e\u043a\u0435\u043d\u043e\u0432; \u043e\u0446\u0435\u043d\u043a\u0430 \u043f\u043e \u0412\u0421\u0415\u041c\u0423 \u0442\u0435\u0441\u0442\u0443 (~10^5 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u2192 \u0442\u044b\u0441\u044f\u0447\u0438 \u043e\u043a\u043e\u043d), \u0447\u0442\u043e\u0431\u044b \u0440\u0430\u0437\u043d\u0438\u0446\u0430 0.05\u20130.3 \u0432 PPL \u0431\u044b\u043b\u0430 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u043c\u0430 \u043d\u0430\u0434 \u0448\u0443\u043c\u043e\u043c; \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e bootstrap-\u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b \u043f\u043e \u043e\u043a\u043d\u0430\u043c \u0438 3 \u0440\u0430\u0437\u043d\u044b\u0445 \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043e\u0447\u043d\u044b\u0445 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u0434\u043b\u044f \u043e\u0446\u0435\u043d\u043a\u0438 variance \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0438.\n\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f: (a) FP16 baseline \u0431\u0435\u0437 \u043a\u0432\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0438\u044f; (b) \u043f\u043e\u043b\u043d\u044b\u0439 INT8, alpha=1.0 (\u0431\u0435\u0437 \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433\u0430) \u2014 quantized baseline; (c) INT8 \u043f\u043e \u0441\u0435\u0442\u043a\u0435 alpha; \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 seed=0, \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u0447\u0435\u043a\u043f\u043e\u0438\u043d\u0442 LLAMA2-7B (fp16, HF), \u043e\u0434\u043d\u0430 \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043e\u0447\u043d\u0430\u044f \u0432\u044b\u0431\u043e\u0440\u043a\u0430 (\u043f\u0435\u0440\u0432\u044b\u0435 N=128 \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432 train WikiText-2) \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u043a\u043e\u043d\u0444\u0438\u0433\u043e\u0432 alpha; \u043e\u0434\u043d\u0430 \u0438 \u0442\u0430 \u0436\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0444\u043e\u0440\u0432\u0430\u0440\u0434-\u043f\u0430\u0441\u043e\u0432 (\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c).\n\n3) \u041a\u041b\u042e\u0427\u0415\u0412\u042b\u0415 \u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u042f \u0418 \u041d\u0415\u041e\u041f\u0420\u0415\u0414\u0415\u041b\u0401\u041d\u041d\u041e\u0421\u0422\u0418 (\u043d\u0435 \u0438\u0437 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432; \u043d\u0430\u0434\u043e \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043a\u0430\u043a \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f):\n- \u0420\u0430\u0437\u0440\u044f\u0434\u043d\u043e\u0441\u0442\u044c: \u0441\u0447\u0438\u0442\u0430\u0435\u043c INT8 (\u0441\u043e\u0433\u043b\u0430\u0441\u0443\u0435\u0442\u0441\u044f \u0441 \u0432\u043e\u043f\u0440\u043e\u0441\u043e\u043c), \u0442\u043e\u0447\u043d\u0430\u044f \u0440\u0430\u0437\u0440\u044f\u0434\u043d\u043e\u0441\u0442\u044c \u0438\u0437 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430.\n- \u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 clipping ratio: \u043f\u0440\u0438\u043d\u044f\u043b\u0438 alpha*max_abs (\u0438 alpha*[min,max] \u0434\u043b\u044f \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u044b\u0445 \u0433\u0440\u0430\u043d\u0438\u0446); \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u0430 \u2014 \u043a\u0432\u0430\u043d\u0442\u0438\u043b\u044c\u043d\u044b\u0439/\u0434\u043e\u043b\u044f-\u0432\u044b\u0431\u0440\u043e\u0441\u043e\u0432 \u043a\u043b\u0438\u043f\u043f\u0438\u043d\u0433, \u043d\u0435 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0430.\n- \u041a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0439 \u0434\u0430\u0442\u0430\u0441\u0435\u0442 \u0434\u043b\u044f PPL: WikiText-2 \u043f\u0440\u0438\u043d\u044f\u0442 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e (\u0432 \u0432\u043e\u043f\u0440\u043e\u0441\u0435 \u043d\u0435 \u043d\u0430\u0437\u0432\u0430\u043d; \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b wikitext-103, c4, lambada).\n- \u041a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043e\u0447\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 (\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a, \u043e\u0431\u044a\u0451\u043c, \u0433\u0434\u0435 \u0431\u0435\u0440\u0451\u043c \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0443 \u0434\u043b\u044f scale) \u2014 \u043d\u0435 \u043e\u0433\u043e\u0432\u043e\u0440\u0435\u043d\u044b; \u043f\u0440\u0438\u043d\u044f\u043b\u0438 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0443 train WikiText-2, N=128.\n- \u041e\u0434\u0438\u043d \u043b\u0438 alpha \u0434\u043b\u044f inputs \u0438 KV, \u0438\u043b\u0438 \u0440\u0430\u0437\u0434\u0435\u043b\u044c\u043d\u044b\u0435; \u0432 \u0433\u043b\u0430\u0432\u043d\u043e\u043c \u0441\u0432\u0438\u043f\u0435 \u2014 \u043e\u0431\u0449\u0438\u0439.\n- \u00ab\u0412\u0445\u043e\u0434\u044b\u00bb = \u043a\u0430\u043a\u0438\u0435 \u0438\u043c\u0435\u043d\u043d\u043e \u0442\u0435\u043d\u0437\u043e\u0440\u044b: \u0430\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u0438 \u043d\u0430 \u0432\u0445\u043e\u0434\u0430\u0445 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0433\u043e \u0441\u043b\u043e\u044f/\u0441\u043a\u0430\u043b\u044f\u0440\u043d\u044b\u0435 \u0442\u043e\u043a\u0435\u043d\u044b; \u0441\u0447\u0438\u0442\u0430\u0435\u043c \u0432\u0441\u0435 matmul-\u0432\u0445\u043e\u0434\u044b (\u0432\u043a\u043b\u044e\u0447\u0430\u044f q/k \u0432\u0445\u043e\u0434\u043d\u044b\u0435 projection), \u0430 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433\u0438.\n- KV-\u043a\u044d\u0448: granularity \u00abchannel\u00bb \u043f\u0440\u0438\u043d\u044f\u0442\u04